import React, { useContext, useState } from "react";
import { AppContext } from "../context/AppContext";
import { GanttChartPolicy as GanttChart } from "../components/GanttChartPolicy";
import { Modal } from "../components/Modal";
import { FormAffectation } from "../components/FormAffectation";

const isRdvTask = value => /^\s*rdv\b/i.test(String(value || ""));
const extractRdvTime = value => {
  const match = String(value || "").match(/(\d{1,2})\s*[h:]\s*(\d{2})/i);
  if (!match) return "";
  return `${String(match[1]).padStart(2, "0")}:${match[2]}`;
};
const formatRdvTask = value => {
  if (!value) return "RDV";
  const [h, m] = String(value).split(":");
  return `RDV • ${String(h || "").padStart(2, "0")}h${String(m || "00").padStart(2, "0")}`;
};

export const GanttPage = ({ onGanttControlsReady }) => {
  const {
    ouvriers,
    chantiers,
    affectations,
    addAffectation,
    updateAffectation,
    deleteAffectation,
    loading
  } = useContext(AppContext);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [selectedOuvrier, setSelectedOuvrier] = useState(null);
  const [selectedDate, setSelectedDate] = useState(null);
  const [editAffectation, setEditAffectation] = useState(null);
  const [editForm, setEditForm] = useState({
    ouvrierId: "",
    dateDebut: "",
    dateFin: "",
    tache: "",
    affectationNom: "",
    chantierId: "",
    isRdv: false,
    rdvHeure: ""
  });
  const [savingEdit, setSavingEdit] = useState(false);
  const [deleteStep, setDeleteStep] = useState(false);

  const parseDate = dateStr => {
    if (!dateStr) return null;
    if (typeof dateStr === "string" && dateStr.includes("/")) {
      const [d, m, y] = dateStr.split("/");
      return new Date(Number(y), Number(m) - 1, Number(d));
    }
    if (typeof dateStr === "string" && /^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
      const [y, m, d] = dateStr.split("-");
      return new Date(Number(y), Number(m) - 1, Number(d));
    }
    return new Date(dateStr);
  };

  const toInputDate = dateValue => {
    const d = parseDate(dateValue);
    if (!d || Number.isNaN(d.getTime())) return "";
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  };

  const toApiDate = isoDate => {
    if (!isoDate) return "";
    const [y, m, d] = isoDate.split("-");
    return `${d}/${m}/${y}`;
  };

  const formatDateLongue = dateValue => {
    const date = parseDate(dateValue);
    if (!date || Number.isNaN(date.getTime())) return "Date inconnue";
    return date.toLocaleDateString("fr-FR", {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric"
    });
  };

  const handleAddAffectation = (ouvrierID, date) => {
    setSelectedOuvrier(ouvriers.find(o => Number(o.id) === Number(ouvrierID)) || null);
    setSelectedDate(date);
    setShowCreateModal(true);
  };

  const handleSubmitAffectation = async formData => {
    if (!selectedOuvrier) return;
    const result = await addAffectation(
      selectedOuvrier.id,
      formData.chantierId,
      formData.dateDebut,
      formData.dateFin,
      formData.tache
    );
    if (result.success) {
      setShowCreateModal(false);
      setSelectedOuvrier(null);
      setSelectedDate(null);
    } else {
      alert("Erreur: " + (result.error || "Impossible de créer l'affectation"));
    }
  };

  const getChantier = affectation =>
    chantiers.find(c => Number(c.id) === Number(affectation?.chantierId)) || null;

  const isHorsGantt = affectation => {
    if (!affectation) return false;
    const chantier = getChantier(affectation);
    return String(affectation.typeAffectation || "").toUpperCase() === "HORS_GANTT" || !chantier;
  };

  const handleAffectationClick = affectation => {
    if (!affectation) return;
    const chantier = getChantier(affectation);
    const horsGantt = isHorsGantt(affectation);
    const rdv = isRdvTask(affectation.tache);

    setEditAffectation(affectation);
    setEditForm({
      ouvrierId: String(affectation.ouvrierID || ""),
      dateDebut: toInputDate(affectation.dateDebut),
      dateFin: toInputDate(affectation.dateFin),
      tache: rdv ? "" : affectation.tache || "",
      affectationNom: horsGantt ? affectation.nomExterne || "" : chantier?.nom || "",
      chantierId: horsGantt ? "" : String(affectation.chantierId || ""),
      isRdv: rdv,
      rdvHeure: rdv ? extractRdvTime(affectation.tache) : ""
    });
    setDeleteStep(false);
  };

  const closeEditModal = () => {
    if (savingEdit) return;
    setEditAffectation(null);
    setDeleteStep(false);
  };

  const handleSaveEdit = async () => {
    if (!editAffectation || savingEdit) return;
    if (!editForm.ouvrierId) {
      alert("Sélectionnez un ouvrier.");
      return;
    }
    if (!editForm.dateDebut || !editForm.dateFin) {
      alert("Les dates de début et de fin sont obligatoires.");
      return;
    }
    if (editForm.dateFin < editForm.dateDebut) {
      alert("La date de fin ne peut pas être avant la date de début.");
      return;
    }
    if (editForm.isRdv && !editForm.rdvHeure) {
      alert("Indiquez l'heure du rendez-vous.");
      return;
    }

    const horsGantt = isHorsGantt(editAffectation);
    if (horsGantt && !editForm.affectationNom.trim()) {
      alert("Le nom de l'affectation est obligatoire.");
      return;
    }
    if (!horsGantt && !editForm.chantierId) {
      alert("Sélectionnez une affectation / un chantier.");
      return;
    }

    const taskToSave = editForm.isRdv
      ? formatRdvTask(editForm.rdvHeure)
      : editForm.tache || "ND";
    const dateDebutApi = toApiDate(editForm.dateDebut);
    const dateFinApi = toApiDate(editForm.dateFin);
    const nouveauOuvrier = Number(editForm.ouvrierId);
    const ouvrierChange = nouveauOuvrier !== Number(editAffectation.ouvrierID);
    const nomLibre = horsGantt ? editForm.affectationNom.trim() : "";
    const chantierId = horsGantt ? "" : editForm.chantierId;

    setSavingEdit(true);
    try {
      if (ouvrierChange) {
        const createResult = await addAffectation(
          nouveauOuvrier,
          chantierId,
          dateDebutApi,
          dateFinApi,
          taskToSave,
          nomLibre,
          horsGantt ? "HORS_GANTT" : "CHANTIER"
        );
        if (!createResult?.success) throw new Error(createResult?.error || "Impossible de déplacer l'affectation");
        const deleteResult = await deleteAffectation(editAffectation.id, false);
        if (!deleteResult?.success) throw new Error(deleteResult?.error || "Impossible de supprimer l'ancienne affectation");
      } else {
        const result = await updateAffectation(
          editAffectation.id,
          dateDebutApi,
          dateFinApi,
          taskToSave,
          "Actif",
          nomLibre,
          chantierId
        );
        if (result?.error) throw new Error(result.error);
      }
      setEditAffectation(null);
      setDeleteStep(false);
    } catch (error) {
      console.error("Erreur modification affectation:", error);
      alert("La modification n'a pas pu être enregistrée.");
    } finally {
      setSavingEdit(false);
    }
  };

  const handleDeleteEdit = async () => {
    if (!editAffectation || savingEdit) return;
    if (!deleteStep) {
      setDeleteStep(true);
      return;
    }

    setSavingEdit(true);
    try {
      const result = await deleteAffectation(editAffectation.id, false);
      if (result?.error) throw new Error(result.error);
      setEditAffectation(null);
      setDeleteStep(false);
    } catch (error) {
      console.error("Erreur suppression affectation:", error);
      alert("La suppression n'a pas pu être effectuée.");
    } finally {
      setSavingEdit(false);
    }
  };

  const editHorsGantt = editAffectation ? isHorsGantt(editAffectation) : false;
  const chantiersActifs = chantiers.filter(c => c.statut === "Actif");
  const ouvriersActifs = ouvriers.filter(o => o.statut === "Actif");

  if (loading) return <div style={{ padding: "1rem" }}>Chargement...</div>;

  const labelStyle = { fontSize: 11, fontWeight: 700, color: "#374151" };
  const inputStyle = {
    width: "100%",
    marginTop: 4,
    padding: "9px 10px",
    borderRadius: 6,
    border: "1px solid #d1d5db",
    boxSizing: "border-box",
    fontSize: 12
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", flex: 1 }}>
      <GanttChart
        ouvriers={ouvriers}
        chantiers={chantiers}
        affectations={affectations}
        onAddAffectation={handleAddAffectation}
        onAffectationClick={handleAffectationClick}
        onControlsReady={onGanttControlsReady}
      />

      <Modal
        isOpen={showCreateModal}
        title="Ajouter une affectation"
        onClose={() => {
          setShowCreateModal(false);
          setSelectedOuvrier(null);
          setSelectedDate(null);
        }}
      >
        {selectedOuvrier && (
          <FormAffectation
            ouvrier={selectedOuvrier}
            chantiers={chantiers}
            onSubmit={handleSubmitAffectation}
            onCancel={() => {
              setShowCreateModal(false);
              setSelectedOuvrier(null);
              setSelectedDate(null);
            }}
            selectedDate={selectedDate}
          />
        )}
      </Modal>

      <Modal isOpen={Boolean(editAffectation)} title="Modifier l'affectation" onClose={closeEditModal}>
        {editAffectation && (
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <div>
                <label style={{ ...labelStyle, color: "#1e40af" }}>Ouvrier — modifiable ✎</label>
                <select
                  value={editForm.ouvrierId}
                  onChange={e => setEditForm(prev => ({ ...prev, ouvrierId: e.target.value }))}
                  disabled={savingEdit}
                  style={{ ...inputStyle, border: "2px solid #2563eb", background: "white" }}
                >
                  {ouvriersActifs.map(ouvrier => (
                    <option key={ouvrier.id} value={ouvrier.id}>{ouvrier.nom}</option>
                  ))}
                </select>
                <div style={{ marginTop: 3, fontSize: 9, color: "#2563eb" }}>
                  Choisissez un autre ouvrier si nécessaire.
                </div>
              </div>

              <div>
                <label style={{ ...labelStyle, color: "#1e40af" }}>Affectation — modifiable ✎</label>
                {editHorsGantt ? (
                  <>
                    <input
                      type="text"
                      value={editForm.affectationNom}
                      onChange={e => setEditForm(prev => ({ ...prev, affectationNom: e.target.value }))}
                      disabled={savingEdit}
                      placeholder="Écrire l'affectation..."
                      autoFocus
                      style={{ ...inputStyle, border: "2px solid #2563eb", outline: "none" }}
                    />
                    <div style={{ marginTop: 3, fontSize: 9, color: "#2563eb" }}>
                      Cliquez dans le champ et écrivez le nouveau texte.
                    </div>
                  </>
                ) : (
                  <>
                    <select
                      value={editForm.chantierId}
                      onChange={e => {
                        const chantier = chantiers.find(c => Number(c.id) === Number(e.target.value));
                        setEditForm(prev => ({
                          ...prev,
                          chantierId: e.target.value,
                          affectationNom: chantier?.nom || ""
                        }));
                      }}
                      disabled={savingEdit}
                      style={{ ...inputStyle, border: "2px solid #2563eb", background: "white" }}
                    >
                      {chantiersActifs.map(chantier => (
                        <option key={chantier.id} value={chantier.id}>{chantier.nom}</option>
                      ))}
                    </select>
                    <div style={{ marginTop: 3, fontSize: 9, color: "#2563eb" }}>
                      Choisissez une autre affectation dans la liste.
                    </div>
                  </>
                )}
              </div>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
              <div>
                <label style={labelStyle}>Date début</label>
                <input
                  type="date"
                  value={editForm.dateDebut}
                  onChange={e => setEditForm(prev => ({ ...prev, dateDebut: e.target.value }))}
                  disabled={savingEdit}
                  style={inputStyle}
                />
              </div>
              <div>
                <label style={labelStyle}>Date fin</label>
                <input
                  type="date"
                  value={editForm.dateFin}
                  onChange={e => setEditForm(prev => ({ ...prev, dateFin: e.target.value }))}
                  disabled={savingEdit}
                  style={inputStyle}
                />
              </div>
            </div>

            <div>
              <label style={labelStyle}>Type</label>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 4 }}>
                <button
                  type="button"
                  onClick={() => setEditForm(prev => ({ ...prev, isRdv: false }))}
                  disabled={savingEdit}
                  style={{
                    padding: "9px 10px",
                    borderRadius: 7,
                    border: !editForm.isRdv ? "2px solid #1e3a8a" : "1px solid #d1d5db",
                    background: !editForm.isRdv ? "#eff6ff" : "white",
                    fontWeight: 700,
                    color: "#1f2937"
                  }}
                >
                  Affectation
                </button>
                <button
                  type="button"
                  onClick={() => setEditForm(prev => ({ ...prev, isRdv: true }))}
                  disabled={savingEdit}
                  style={{
                    padding: "9px 10px",
                    borderRadius: 7,
                    border: editForm.isRdv ? "2px solid #7c3aed" : "1px solid #d1d5db",
                    background: editForm.isRdv ? "#f5f3ff" : "white",
                    fontWeight: 700,
                    color: "#1f2937"
                  }}
                >
                  RDV
                </button>
              </div>
            </div>

            {editForm.isRdv ? (
              <div>
                <label style={labelStyle}>Heure du RDV</label>
                <input
                  type="time"
                  value={editForm.rdvHeure}
                  onChange={e => setEditForm(prev => ({ ...prev, rdvHeure: e.target.value }))}
                  disabled={savingEdit}
                  style={inputStyle}
                />
              </div>
            ) : (
              <div>
                <label style={labelStyle}>Tâche</label>
                <input
                  type="text"
                  value={editForm.tache}
                  onChange={e => setEditForm(prev => ({ ...prev, tache: e.target.value }))}
                  disabled={savingEdit}
                  style={inputStyle}
                />
              </div>
            )}

            <div style={{ fontSize: 10, color: "#6b7280" }}>
              Affectation actuelle : {formatDateLongue(editAffectation.dateDebut)} → {formatDateLongue(editAffectation.dateFin)}
            </div>

            {deleteStep && (
              <div style={{
                background: "#fef2f2",
                border: "1px solid #fecaca",
                borderRadius: 8,
                padding: 10,
                fontSize: 11,
                color: "#991b1b",
                fontWeight: 700
              }}>
                Confirmer la suppression de cette affectation ?
              </div>
            )}

            <div style={{ display: "flex", gap: 8, justifyContent: "space-between", flexWrap: "wrap" }}>
              <button
                type="button"
                onClick={handleDeleteEdit}
                disabled={savingEdit}
                style={{
                  padding: "9px 12px",
                  borderRadius: 7,
                  border: "1px solid #dc2626",
                  background: deleteStep ? "#dc2626" : "white",
                  color: deleteStep ? "white" : "#dc2626",
                  fontWeight: 700
                }}
              >
                {deleteStep ? "Confirmer suppression" : "Supprimer"}
              </button>

              <div style={{ display: "flex", gap: 8 }}>
                <button
                  type="button"
                  onClick={closeEditModal}
                  disabled={savingEdit}
                  style={{
                    padding: "9px 12px",
                    borderRadius: 7,
                    border: "1px solid #d1d5db",
                    background: "white",
                    fontWeight: 700
                  }}
                >
                  Annuler
                </button>
                <button
                  type="button"
                  onClick={handleSaveEdit}
                  disabled={savingEdit}
                  style={{
                    padding: "9px 12px",
                    borderRadius: 7,
                    border: "1px solid #1e3a8a",
                    background: "#1e3a8a",
                    color: "white",
                    fontWeight: 700
                  }}
                >
                  {savingEdit ? "Enregistrement..." : "Enregistrer"}
                </button>
              </div>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};
